function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function drawAvatar(){const c=$('#avatar'),x=c.getContext('2d'),race=races[selectedRace],p=palettes[selectedRace],tone=race.colors[activePalette]||p.skin,energy=energies[selectedEnergy].color;x.clearRect(0,0,c.width,c.height);x.imageSmoothingEnabled=false;
// Aura and floor light
x.globalAlpha=.13;x.fillStyle=energy;x.beginPath();x.ellipse(90,165,48,74,0,0,Math.PI*2);x.fill();x.globalAlpha=1;
const rect=(a,b,w,h,col)=>{x.fillStyle=col;x.fillRect(a,b,w,h)},outline=(a,b,w,h,col='#171b26')=>{x.strokeStyle=col;x.lineWidth=3;x.strokeRect(a+1.5,b+1.5,w-3,h-3)};
// Energy sparks
for(let i=0;i<8;i++){const xx=17+i*21, yy=52+(i%3)*39;rect(xx,yy,2,7,energy);rect(xx-2,yy+3,6,2,energy)}
// Back hair / head appendages
if(selectedRace===2){rect(62,46,9,19,p.hair);rect(109,46,9,19,p.hair);rect(57,53,7,6,p.hair);rect(116,53,7,6,p.hair)}
if(selectedRace===3){rect(87,21,7,25,p.hair);rect(90,16,5,11,p.hair)}
// Legs and boots
rect(67,148,19,46,tone);rect(94,148,19,46,tone);rect(61,185,28,17,'#171c29');rect(92,185,29,17,'#171c29');rect(62,184,26,5,p.trim);rect(94,184,26,5,p.trim);outline(61,184,28,19);
// Arms / gloves
rect(47,93,18,47,tone);rect(115,93,18,47,tone);rect(45,133,19,13,p.trim);rect(116,133,19,13,p.trim);rect(46,145,17,9,'#171c29');rect(117,145,17,9,'#171c29');outline(45,91,20,58);outline(115,91,20,58);
// Body suit silhouette
rect(64,84,53,71,p.suit);rect(70,80,42,14,p.suit);outline(64,82,53,74);rect(68,91,45,7,p.trim);rect(87,98,8,50,'#ffffff14');
// Chest armor panels
rect(69,101,16,27,'#ffffff10');rect(97,101,15,27,'#00000018');rect(68,132,46,7,p.trim);rect(79,142,24,7,'#171c29');
// Neck and head
rect(81,69,18,19,tone);rect(67,39,47,39,tone);outline(65,36,51,46);rect(72,58,8,3,'#222435');rect(99,58,8,3,'#222435');rect(76,57,4,3,'#171925');rect(101,57,4,3,'#171925');rect(87,69,7,2,'#ac6570');
// Hair styles
if(selectedRace===0||selectedRace===1||selectedRace===4){rect(67,33,48,13,p.hair);rect(63,40,9,19,p.hair);rect(72,26,11,15,p.hair);rect(81,19,12,22,p.hair);rect(92,24,11,17,p.hair);rect(103,32,12,14,p.hair);rect(63,44,7,11,p.hair);rect(76,34,8,6,'#ffffff18');}
else if(selectedRace===2){rect(67,33,48,12,p.hair);rect(60,40,8,14,p.hair);rect(113,40,8,14,p.hair);rect(77,29,8,8,'#fff');rect(95,29,8,8,'#fff');rect(68,45,5,7,'#b7b9d1');}
else if(selectedRace===3){rect(66,36,49,13,p.hair);rect(64,43,9,15,p.hair);rect(108,43,9,15,p.hair);rect(81,29,17,9,p.hair);rect(86,19,8,16,p.hair);rect(77,34,6,9,p.hair);}
else {rect(67,33,48,13,p.hair);rect(63,40,9,15,p.hair);rect(72,28,12,13,p.hair);rect(87,24,10,17,p.hair);rect(101,31,13,14,p.hair);}
// Unique markings / tech accents
if(selectedRace===5){rect(64,52,5,11,'#79d9ee');rect(110,52,5,11,'#79d9ee');rect(72,46,4,2,'#e7faff');rect(103,46,4,2,'#e7faff')}
if(selectedRace===6){for(let i=0;i<5;i++)rect(69+i*9,104+(i%2)*8,3,3,'#8fe57b')}
if(selectedRace===2){rect(65,63,5,8,p.trim);rect(110,63,5,8,p.trim)}
// Shoulder plates and emblem
rect(59,88,10,15,p.trim);rect(112,88,10,15,p.trim);rect(86,110,9,12,energy);rect(89,107,3,18,'#ffffff55');
