rect(70,82,8,3,'#ffffff31');rect(102,82,8,3,'#ffffff20');rect(69,151,9,3,'#ffffff25');
}
function startWorld(){if(!current()){showToast('CREA O SELECCIONA UN PERSONAJE');return}worldOpen=true;$('#creatorScreen').style.display='none';document.querySelector('header').style.display='none';document.querySelector('footer').style.display='none';$('#world').style.display='block';$('#worldName').textContent=current().name.toUpperCase();$('#worldRace').textContent=`NIVEL 01 · ${races[current().race].name.toUpperCase()}`;resizeWorld();drawWorld();}
function backToCreator(){worldOpen=false;$('#world').style.display='none';$('#creatorScreen').style.display='flex';document.querySelector('header').style.display='flex';document.querySelector('footer').style.display='flex';render()}
$('#backBtn').onclick=backToCreator;
$('#createBtn').onclick=()=>{const name=safeName($('#nameInput').value)||['Nova','Akiro','Kira'][selectedSlot];slots[selectedSlot]={name,race:selectedRace,tone:activePalette,energy:energies[selectedEnergy].color};save();$('#nameInput').value=name;render();startWorld()};
// Isometric-feeling pixel-art landing valley; player moves freely around the beacon.
const wc=$('#worldCanvas'),wctx=wc.getContext('2d');let player={x:160,y:120,dir:0,walk:0};const keys={};
function resizeWorld(){wc.width=320;wc.height=180;}
function drawWorld(){if(!worldOpen)return;const x=wctx;x.imageSmoothingEnabled=false;x.clearRect(0,0,320,180);
// sky, stars and distant moons
let sky=x.createLinearGradient(0,0,0,115);sky.addColorStop(0,'#1b2743');sky.addColorStop(1,'#667d87');x.fillStyle=sky;x.fillRect(0,0,320,115);x.fillStyle='#f6d9a1';x.beginPath();x.arc(252,32,12,0,7);x.fill();x.fillStyle='#ffedc5';x.fillRect(249,29,6,6);
for(let i=0;i<32;i++){const sx=(i*67+11)%320,sy=(i*29+7)%76;x.fillStyle=i%4?'#dce7e88a':'#ffe6b4';x.fillRect(sx,sy,1,1)}
// layered mountain silhouettes
x.fillStyle='#435469';x.beginPath();x.moveTo(0,105);for(let i=0;i<=320;i+=32)x.lineTo(i,72+((i*7)%27));x.lineTo(320,125);x.lineTo(0,125);x.fill();x.fillStyle='#334553';x.beginPath();x.moveTo(0,113);for(let i=0;i<=320;i+=40)x.lineTo(i,87+((i*11)%24));x.lineTo(320,130);x.lineTo(0,130);x.fill();
// far mesas
x.fillStyle='#7d9a89';x.fillRect(0,108,320,30);x.fillStyle='#8cae8c';x.fillRect(0,114,320,2);x.fillRect(33,108,5,2);x.fillRect(254,111,8,2);
// grass plane
x.fillStyle='#718c6d';x.fillRect(0,127,320,53);x.fillStyle='#89a576';for(let i=0;i<100;i++){let px=(i*41+3)%320,py=129+(i*23)%49;x.fillRect(px,py,2,1)}
// winding pale path
x.fillStyle='#c1ad83';x.fillRect(145,128,40,52);x.fillRect(137,137,55,18);x.fillRect(128,155,73,16);x.fillStyle='#d5c59d';x.fillRect(151,130,2,46);x.fillRect(140,142,47,2);
// small outpost buildings
x.fillStyle='#36404d';x.fillRect(26,88,48,41);x.fillRect(20,101,8,28);x.fillStyle='#b78469';x.fillRect(22,87,54,9);x.fillRect(31,81,39,7);x.fillStyle='#e7c68e';x.fillRect(35,103,10,14);x.fillRect(54,101,11,8);x.fillStyle='#f4d296';x.fillRect(37,105,6,10);x.fillRect(57,103,5,4);x.fillStyle='#52646a';x.fillRect(27,119,46,10);
// antenna and flags
x.fillStyle='#d8d0b1';x.fillRect(51,67,2,16);x.fillRect(48,68,8,2);x.fillStyle='#f08780';x.fillRect(53,70,7,4);
// rocks, plants
for(const [rx,ry] of [[99,131],[235,145],[281,126],[84,160],[221,120]]){x.fillStyle='#52645b';x.fillRect(rx,ry,7,4);x.fillRect(rx+2,ry-3,4,4);x.fillStyle='#a5af84';x.fillRect(rx+3,ry-2,2,2)}
for(const [tx,ty] of [[13,130],[300,143],[270,116],[111,146]]){x.fillStyle='#496e59';x.fillRect(tx+4,ty-7,3,9);x.fillRect(tx,ty-5,4,4);x.fillRect(tx+7,ty-4,4,5);x.fillStyle='#d4a266';x.fillRect(tx+5,ty-9,2,2)}
// glowing arrival beacon
x.globalAlpha=.18;x.fillStyle=current()?.energy||'#76e6e1';x.fillRect(164,103,11,28);x.globalAlpha=1;x.fillStyle='#d4d8c6';x.fillRect(162,122,15,8);x.fillRect(165,112,9,13);x.fillStyle=current()?.energy||'#76e6e1';x.fillRect(167,108,5,8);x.fillStyle='#f6e8bd';x.fillRect(168,105,3,3);
// character sprite, pixel drawing at native scale
const s=current(),race=races[s?.race||0],sk=palettes[s?.race||0].skin;const px=Math.round(player.x),py=Math.round(player.y);x.fillStyle='#25313c66';x.fillRect(px-5,py+4,11,2);x.fillStyle='#273c60';x.fillRect(px-4,py-10,8,11);x.fillStyle=sk;x.fillRect(px-3,py-16,6,6);x.fillStyle=race.hair;x.fillRect(px-4,py-18,8,3);x.fillRect(px-4,py-16,2,3);x.fillStyle=race.accent;x.fillRect(px-4,py-8,8,2);x.fillStyle='#f0c46d';x.fillRect(px-1,py-5,2,2);if(player.walk%2<1){x.fillStyle='#1b2230';x.fillRect(px-4,py,3,3);x.fillRect(px+1,py,3,3)}else{x.fillStyle='#1b2230';x.fillRect(px-3,py,3,3);x.fillRect(px+1,py,3,3)}
// legend
x.fillStyle='#e8f4dc';x.font='5px monospace';x.fillText('NEXO ESTELAR  /  ZONA SEGURA',7,8);
// proximity marker
if(Math.abs(player.x-169)<16&&Math.abs(player.y-117)<17){x.fillStyle='#fff4c4';x.font='6px monospace';x.fillText('PUNTO DE LLEGADA',139,96)}
requestAnimationFrame(drawWorld)}
function move(e,on){const d=e.currentTarget.dataset.dir;keys[d]=on;e.preventDefault()}
document.querySelectorAll('.touch-pad button').forEach(b=>{b.addEventListener('pointerdown',e=>move(e,true));b.addEventListener('pointerup',e=>move(e,false));b.addEventListener('pointerleave',e=>move(e,false));b.addEventListener('pointercancel',e=>move(e,false))});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){keys[k]=true;e.preventDefault()}});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function updatePlayer(){if(!worldOpen)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(keys.right?1:0)-(keys.left?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(keys.down?1:0)-(keys.up?1:0);if(dx||dy){let len=Math.hypot(dx,dy);player.x=Math.max(8,Math.min(312,player.x+dx/len*.85));player.y=Math.max(76,Math.min(171,player.y+dy/len*.65));player.walk+=.24}requestAnimationFrame(updatePlayer)}
requestAnimationFrame(updatePlayer);
// Keyboard race selection while in the creator.
window.addEventListener('keydown',e=>{if(worldOpen)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();selectedRace=(selectedRace+(e.key==='ArrowDown'?1:6))%7;activePalette=selectedRace;render()}if(e.key==='Enter'&&document.activeElement!==$('#nameInput'))$('#createBtn').click()});
render();
</script></body></html>

