 header{height:72px;flex:none;border-bottom:1px solid #ffffff12;display:flex;align-items:center;padding:0 4vw;gap:14px;position:relative;z-index:2;background:#11141dcc}.brand{display:flex;align-items:center;gap:12px;min-width:220px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid var(--gold);color:var(--gold);font-size:21px;transform:rotate(45deg);box-shadow:0 0 20px #ffca6624}.brand-mark span{transform:rotate(-45deg)}.brand-title{font-size:13px;font-weight:900;letter-spacing:.25em}.brand-sub{font-size:8px;letter-spacing:.18em;color:#9da5b3;margin-top:3px}.head-center{margin:auto;display:flex;align-items:center;gap:12px;color:#aab1bf;font:10px ui-monospace,monospace;letter-spacing:.13em}.live-dot{height:7px;width:7px;border-radius:50%;background:#76e6e1;box-shadow:0 0 10px #76e6e1}.header-right{min-width:220px;text-align:right;font:10px ui-monospace,monospace;color:#828c9d;letter-spacing:.08em}.header-right b{color:var(--gold);font-weight:600}
 main{position:relative;z-index:1;flex:1;min-height:0;display:flex;flex-direction:column;padding:20px 4vw 14px}.eyebrow{font:10px ui-monospace,monospace;letter-spacing:.22em;text-transform:uppercase;color:var(--cyan);display:flex;align-items:center;gap:9px}.eyebrow:before{content:"";width:22px;height:1px;background:var(--cyan)}.title-row{display:flex;align-items:end;justify-content:space-between;margin:9px 0 14px}.title-row h1{font-size:clamp(22px,2.4vw,32px);line-height:1;margin:0;font-weight:800;letter-spacing:-.04em}.title-row h1 span{color:var(--gold)}.title-caption{font:10px ui-monospace,monospace;color:#8f98a9;letter-spacing:.1em;text-align:right;line-height:1.6}
 .creator{display:grid;grid-template-columns:minmax(210px, .82fr) minmax(270px,1.3fr) minmax(250px,.95fr);gap:12px;flex:1;min-height:0}.panel{background:linear-gradient(145deg,#1c2230e8,#151a25ed);border:1px solid #ffffff15;position:relative;min-height:0;box-shadow:0 10px 40px #0002}.panel:before{content:"";position:absolute;top:-1px;left:-1px;width:28px;height:2px;background:var(--cyan)}.panel-head{padding:14px 15px 11px;border-bottom:1px solid #ffffff12;display:flex;align-items:center;justify-content:space-between}.panel-title{font-size:10px;font-weight:800;letter-spacing:.16em}.panel-count{font:9px ui-monospace,monospace;color:#788396}.race-list{height:calc(100% - 45px);overflow:auto;padding:7px}.race-btn{width:100%;height:47px;border:1px solid transparent;background:transparent;display:flex;align-items:center;text-align:left;padding:0 10px;gap:10px;margin-bottom:3px;transition:.16s}.race-btn:hover{background:#ffffff09}.race-btn.selected{background:linear-gradient(90deg,#76e6e115,#76e6e103);border-color:#76e6e13a}.race-icon{width:28px;height:28px;display:grid;place-items:center;color:var(--race);font-size:17px;background:#ffffff09;border:1px solid #ffffff11}.race-name{display:block;font-size:11px;font-weight:700;flex:1}.race-desc{display:block;font:8px ui-monospace,monospace;color:#8490a2;text-transform:uppercase;letter-spacing:.07em;margin-top:3px}.race-arrow{color:#697487;font-size:13px}.selected .race-arrow{color:var(--cyan)}
